declare_lint ! { # [doc = " The `type_alias_bounds` lint detects bounds in type aliases."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " type SendVec<T: Send> = Vec<T>;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Trait and lifetime bounds on generic parameters and in where clauses of"] # [doc = " type aliases are not checked at usage sites of the type alias. Moreover,"] # [doc = " they are not thoroughly checked for correctness at their definition site"] # [doc = " either similar to the aliased type."] # [doc = ""] # [doc = " This is a known limitation of the type checker that may be lifted in a"] # [doc = " future edition. Permitting such bounds in light of this was unintentional."] # [doc = ""] # [doc = " While these bounds may have secondary effects such as enabling the use of"] # [doc = " \"shorthand\" associated type paths[^1] and affecting the default trait"] # [doc = " object lifetime[^2] of trait object types passed to the type alias, this"] # [doc = " should not have been allowed until the aforementioned restrictions of the"] # [doc = " type checker have been lifted."] # [doc = ""] # [doc = " Using such bounds is highly discouraged as they are actively misleading."] # [doc = ""] # [doc = " [^1]: I.e., paths of the form `T::Assoc` where `T` is a type parameter"] # [doc = " bounded by trait `Trait` which defines an associated type called `Assoc`"] # [doc = " as opposed to a fully qualified path of the form `<T as Trait>::Assoc`."] # [doc = " [^2]: <https://doc.rust-lang.org/reference/lifetime-elision.html#default-trait-object-lifetimes>"] TYPE_ALIAS_BOUNDS , Warn , "bounds in type aliases are not enforced" }